{
  "passageId": "dopamine-motor-control",
  "items": [
    {
      "id": "R1",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "외부에서 도파민을 섭취할 수 있어도 뇌로 들어가지는 못한다는 한계를 제시한다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "외부 도파민의 장벽 통과 불가능성을 근거로 뇌의 신경 경로를 이동할 수 있는 도파민의 출처를 한정한다."
    },
    {
      "id": "R3",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "외부 도파민이 뇌에 들어갈 수 없다는 사실로부터 뇌에서 신경 전달 물질로 작용하는 도파민의 출처에 관한 결론을 도출한다."
    },
    {
      "id": "R4",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "신호 전달에서 담당하는 역할을 기준으로 시냅스 전 뉴런의 전달 기능과 시냅스 후 뉴런의 수신 기능을 대비한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "신경 전달 물질의 일반적인 신호 전달 과정을 그 일종인 도파민의 저장·분비·결합 과정으로 구체화한다."
    },
    {
      "id": "R6",
      "type": "PROCESS",
      "otherName": "",
      "reason": "티로신이 뉴런에 흡수되는 단계 다음에 흡수된 티로신으로 레보도파를 합성하는 단계가 이어진다."
    },
    {
      "id": "R7",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 합성된 레보도파를 재료로 다음 단계의 도파민 합성이 진행된다."
    },
    {
      "id": "R8",
      "type": "PROCESS",
      "otherName": "",
      "reason": "도파민 합성 단계의 산출물이 저장·분비·수용체 결합 단계로 이어지는 순서를 설명한다."
    },
    {
      "id": "R9",
      "type": "PROCESS",
      "otherName": "",
      "reason": "두 문장의 연결은 도파민이 소포에 저장된 뒤 분비되는 단계적 순서이며 활성화 조건은 뒤 문장 내부에 있다."
    },
    {
      "id": "R10",
      "type": "PROCESS",
      "otherName": "",
      "reason": "시냅스 틈으로 분비된 도파민이 다음 단계에서 수용체에 결합하는 순서를 설명한다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "도파민의 수용체 결합이 실제로 시냅스 후 뉴런으로의 신호 전달을 일으킨다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞에서 언급한 도파민 수용체를 두 계열과 각각의 기능으로 더 자세히 설명한다."
    },
    {
      "id": "R13",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "뉴런 내 신호 전달 활성에 미치는 영향을 기준으로 D1의 유도 작용과 D2의 억제 작용을 대비한다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "D2 계열의 억제성 작용을 그 일부인 도파민성 뉴런의 자가 수용체에서 나타나는 작용으로 구체화한다."
    },
    {
      "id": "R15",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "도파민성 뉴런에 위치하는 D2 계열 수용체에 자가 수용체라는 이름을 붙인다."
    },
    {
      "id": "R16",
      "type": "CAUSE",
      "otherName": "",
      "reason": "자가 수용체 결합에 따른 신호 전달 활성화의 억제가 도파민 분비 중단을 일으킨다."
    },
    {
      "id": "R17",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "분비된 도파민이 자가 수용체를 통해 추가 분비를 중단시키는 기제로부터 자기 조절이 가능하다는 판단을 도출한다."
    },
    {
      "id": "R18",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "도파민의 분비 과정에서 분비된 도파민에 의한 자기 조절 기제로 논의가 확장된다."
    },
    {
      "id": "R19",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "분비된 도파민이 수용체에 결합한다는 일반적 설명에 대해 일부는 결합하지 않고 재흡수된다는 예외를 제시한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "도파민성 뉴런에 위치한다고 소개한 DAT가 어떤 기능을 하는지 재흡수 작용으로 상세히 설명한다."
    },
    {
      "id": "R21",
      "type": "PROCESS",
      "otherName": "",
      "reason": "재흡수된 도파민이 이후 저장과 재사용 단계로 이어지는 순서를 설명한다."
    },
    {
      "id": "R22",
      "type": "PROCESS",
      "otherName": "",
      "reason": "재흡수 단계 이후 그 도파민이 뉴런 안에서 분해되는 후속 처리 과정을 설명한다."
    },
    {
      "id": "R23",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "재흡수된 도파민의 후속 처리라는 같은 기준에서 재사용과 분해라는 서로 다른 결과를 대비한다."
    },
    {
      "id": "R24",
      "type": "CONDITION",
      "otherName": "",
      "reason": "DAT가 없는 뉴런이라는 경우를 설정하고 그 경우 도파민이 뉴런 밖에서 분해됨을 설명한다."
    },
    {
      "id": "R25",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "DAT를 통한 재흡수와 세포 내 처리에 대해 모든 뉴런에 DAT가 있는 것은 아니라는 적용상의 한계와 예외를 제시한다."
    },
    {
      "id": "R26",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "도파민이 관여하는 여러 기능 중 운동 조절을 수의적 운동의 조절로 구체화한다."
    },
    {
      "id": "R27",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "두 신경 경로가 운동을 조절한다는 설명을 직접 경로의 구체적인 작동 기제로 풀어낸다."
    },
    {
      "id": "R28",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "두 신경 경로가 운동을 조절한다는 설명을 간접 경로의 구체적인 작동 기제로 풀어낸다."
    },
    {
      "id": "R29",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "선조체 뉴런이 가바를 합성하는 뉴런이라는 사실이 활성화 시 가바가 분비된다는 설명을 뒷받침한다."
    },
    {
      "id": "R30",
      "type": "CAUSE",
      "otherName": "",
      "reason": "선조체에서 내측 창백핵으로 분비된 가바가 내측 창백핵 뉴런의 활성을 억제한다."
    },
    {
      "id": "R31",
      "type": "CAUSE",
      "otherName": "",
      "reason": "내측 창백핵 뉴런의 활성 억제가 시상으로의 가바 분비 중단을 일으킨다."
    },
    {
      "id": "R32",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "내측 창백핵 뉴런이 가바성 뉴런이라는 사실이 그 활성 억제를 가바 분비 여부와 연결하는 설명의 근거가 된다."
    },
    {
      "id": "R33",
      "type": "CAUSE",
      "otherName": "",
      "reason": "시상으로 가바가 분비되지 않는 것이 시상 뉴런의 억제를 해제하여 활성화를 일으킨다."
    },
    {
      "id": "R34",
      "type": "CAUSE",
      "otherName": "",
      "reason": "시상의 글루타메이트성 뉴런이 활성화되어 대뇌 피질 운동 영역으로 글루타메이트가 분비된다."
    },
    {
      "id": "R35",
      "type": "CAUSE",
      "otherName": "",
      "reason": "대뇌 피질 운동 영역으로의 글루타메이트 분비가 실제 운동의 시작으로 이어진다."
    },
    {
      "id": "R36",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "선조체와 내측 창백핵의 연결 방식을 기준으로 직접 연결과 다른 부위를 거치는 간접 연결을 대비한다."
    },
    {
      "id": "R37",
      "type": "CAUSE",
      "otherName": "",
      "reason": "간접 경로에서 내측 창백핵으로 분비된 글루타메이트가 내측 창백핵 뉴런을 활성화한다."
    },
    {
      "id": "R38",
      "type": "CAUSE",
      "otherName": "",
      "reason": "내측 창백핵 뉴런의 활성화가 직접 경로에서의 억제와 반대되는 후속 신경 작용을 일으킨다."
    },
    {
      "id": "R39",
      "type": "CAUSE",
      "otherName": "",
      "reason": "간접 경로에서 일어나는 직접 경로와 상반된 작용이 운동 차단을 일으킨다."
    },
    {
      "id": "R40",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "운동에 미치는 영향을 기준으로 직접 경로의 운동 시작 작용과 간접 경로의 운동 차단 작용을 대비한다."
    },
    {
      "id": "R41",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "두 경로 자체의 운동 조절 기제에서 도파민이 그 경로들에 미치는 영향으로 논의가 확장된다."
    },
    {
      "id": "R42",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "흑질 뉴런이 선조체에 연결된다는 해부학적 사실이 두 경로를 통한 운동 조절 영향의 설명을 뒷받침한다."
    },
    {
      "id": "R43",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 설명한 D1 수용체의 흥분성 작용 원리를 직접 경로에 대한 도파민의 영향에 적용한다."
    },
    {
      "id": "R44",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "직접 경로에 D1 수용체가 밀집한다는 사실을 근거로 도파민이 직접 경로를 활성화한다는 설명을 도출한다."
    },
    {
      "id": "R45",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 설명한 D2 수용체의 억제성 작용 원리를 간접 경로에 대한 도파민의 영향에 적용한다."
    },
    {
      "id": "R46",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "간접 경로에 D2 수용체가 밀집한다는 사실을 근거로 도파민이 간접 경로를 억제한다는 설명을 도출한다."
    },
    {
      "id": "R47",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "도파민이 각 경로의 활성에 미치는 영향을 기준으로 직접 경로의 활성화와 간접 경로의 억제를 대비한다."
    },
    {
      "id": "R48",
      "type": "CAUSE",
      "otherName": "",
      "reason": "운동을 시작시키는 직접 경로의 활성화가 목표 운동의 시작을 수월하게 하는 실제 작용을 한다."
    },
    {
      "id": "R49",
      "type": "CAUSE",
      "otherName": "",
      "reason": "운동을 차단하는 간접 경로의 억제가 목표 운동의 시작을 수월하게 하는 실제 작용을 한다."
    },
    {
      "id": "R50",
      "type": "CAUSE",
      "otherName": "",
      "reason": "목표 운동의 시작이 수월해지는 것이 운동 촉진이라는 결과로 이어진다."
    },
    {
      "id": "R51",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "직접 경로가 운동을 시작시킨다는 기제가 그 경로의 활성화로 운동 시작이 쉬워진다는 설명을 뒷받침한다."
    },
    {
      "id": "R52",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "간접 경로가 운동을 차단한다는 기제가 그 경로의 억제로 운동 시작이 쉬워진다는 설명을 뒷받침한다."
    }
  ]
}

